\title{SAVOR: Self-Aware Visual Grounding via\\Confidence-Calibrated Reinforcement Learning\\for Multimodal Hallucination Mitigation}
%
\titlerunning{SAVOR: Self-Aware Visual Grounding via Calibrated RL}
%
\author{Zixiu Ding\inst{1,2} \and Zilin Zhao\inst{2} \and Yingjie He\inst{2} \and Xinlang Kang\inst{2} \and Guansu Wang\inst{2} \and Wei Zhang\Letter}
